    segment. Shared edges are traversed once by the tree, so data
    forwarded along common segments is paid once per partition instead
    of once per destination-path, cutting redundant transfers.

    Continuity fix vs. prior attempt: we store the full contiguous path
    from src to every tree node (node_path). When attaching a new dst
    through tree node t, its recorded path is node_path[t] + segment,
    so every partition's edge list is a valid contiguous src->dst path.
    All partitions of a destination reuse the same tree path.
    """
    def weight_fn(u, v, d):
        if u == v:
            return 0
        c = d.get("cost")
        return c if c is not None else float("inf")

    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    tree_nodes = {src}
    node_path = {src: [src]}  # full contiguous path from src to each tree node
    remaining = [d for d in dsts if d != src]

    # Dests equal to src need no transfer edges (empty path is fine)
    for d in dsts:
        if d == src:
            for j in range(num_partitions):
                bc_topology.set_dst_partition_paths(d, j, [])

    while remaining:
        dist, paths = nx.multi_source_dijkstra(G, list(tree_nodes), weight=weight_fn)
        best = None  # (dist, dst, attach_node, segment)
        for d in remaining:
            if d in dist and (best is None or dist[d] < best[0]):
                seg = paths[d]
                best = (dist[d], d, seg[0], seg)
        if best is None:
            # Some destination unreachable: fall back to plain Dijkstra
            # paths from src so the topology is still populated.
            def wf2(u, v, dd):
                c = dd.get("cost")
                return c if c is not None else float("inf")
            _, dists2 = nx.single_source_dijkstra(G, src, weight=wf2)
            for d in remaining:
                p = dists2.get(d)
