                            s, t = p[i], p[i + 1]
                            bc_topology.append_dst_partition_path(d, j, [s, t, G[s][t]])
            break

        _, d, attach, seg = best
        full = node_path[attach] + seg[1:]
        # Register full contiguous paths for every new node on this segment
        prefix = node_path[attach]
        for i in range(len(seg) - 1):
            n = seg[i + 1]
            node_path[n] = prefix + [n]
            tree_nodes.add(n)
        # Record the dst's full contiguous path for every partition
